def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "grasp_cd1": And([
            self.laptop_on_desk,
            self.cd_behind_laptop,
            Not(self.laptop_moved)
        ]),
        "grasp_cd2": And([
            self.laptop_on_desk,
            self.cd_behind_laptop,
            Not(self.laptop_moved)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
